// this function is using for picking replies
// array is the placeholder
// so later when I use function i don't need to write these again
function pick(array) {
    let i = Math.floor(Math.random() * array.length);
    return array[i];
}

// a function detects if posts contain bad words
// so god will "know" what to reply
function detect(message) {
    // because my keywords are all in lowercase
    // learnt this toLowerCase from AI, in coding.md file
    let lower = message.toLowerCase()
    for (let word of badWords) {
        if (lower.includes(word)){
            return true;
        }
    }
}

